    'LAND_COST_BELOW_LOCALITY': { term: 'land_cost_position', kind: 'watch', rule: bi('₪/יח״ד של המגרש ≤ הרבעון התחתון של ≥ 5 מגרשי הצעה תחרותית באותו יישוב ומסלול ב-36 חודשים (המכרז הזה מוחרג)', 'the lot\'s ₪/unit ≤ the lower quartile of ≥ 5 competitive-bid lots in the same locality and track over 36 months (this tender excluded)') },
    'LOTTERY_DEMAND_ABOVE_LOCALITY': { term: 'lottery_demand_position', kind: 'watch', rule: bi('נרשמים ליח״ד בהגרלה הראשונה ≥ הרבעון העליון של ≥ 5 הגרלות ראשונות אחרות ביישוב', 'applicants per unit in the first lottery ≥ the upper quartile of ≥ 5 other first lotteries in the locality') },
    'LOTTERY_DEMAND_BELOW_LOCALITY': { term: 'lottery_demand_position', kind: 'watch', rule: bi('נרשמים ליח״ד בהגרלה הראשונה ≤ הרבעון התחתון של ≥ 5 הגרלות ראשונות אחרות ביישוב', 'applicants per unit in the first lottery ≤ the lower quartile of ≥ 5 other first lotteries in the locality') },
    'LOTTERY_UNDERSUBSCRIBED': { term: 'applicants_per_unit', kind: 'risk', rule: bi('פחות מנרשם אחד ליח״ד בהגרלה ראשונה של ≥ 20 יח״ד', 'fewer than one applicant per unit in a first lottery of ≥ 20 units') },
    'PLAN_JOINED': { term: 'units_after_plan', kind: 'info', rule: bi('תוכנית מאושרת ומתוארכת מצורפת למכרז במספר תוכנית מדויק (לעולם לא לפי שם או גאומטריה)', 'a dated approved plan joined to the tender by exact plan number (never by name or geometry)') },
    'PROJECT_CONSTRUCTION_REPORT': { term: 'construction_progress_report', kind: 'info', rule: bi('דיווח התקדמות של משב״ש מצורף למגרש בגוש/חלקה מדויקים עם מבנה שהחל או הושלם (נכון ל-2024-03)', 'a MoCH progress report joined to the lot by exact block/parcel with a building started or completed (as of 2024-03)') },
    'RE_TENDERED_LOT': { term: 'tender_units_awarded', kind: 'info', rule: bi('מכרז קודם ברשימה החיה שיווק את אותו תיק מגרש (TikID של רמ״י) — שיווק חוזר', 'an earlier tender in the live list marketed the same lot file (the Authority\'s TikID) — a re-tender') },
    /* market dossier / scan */
    'sales-momentum-up': { term: 'sales_momentum_3m', kind: 'watch', rule: bi('מומנטום 3 חודשים ≥ +10% בסדרה הרשמית (ארצי / מחוז; יישוב מציג את אות המחוז שלו מסומן "רמת מחוז" — ברדאר לעולם לא מיוחס ליישוב; לא במדגם קטן)', '3-month momentum ≥ +10 % in the official series (national / district; a locality shows its district\'s signal labelled "district level" — in the radar never attributed to a locality; not on a small sample)') },
