    'failed-tenders': { term: 'failed_tender_ratio', kind: 'risk', rule: bi('≥ 30% מתוך ≥ 5 מכרזים נוכחיים נדונו ללא זוכה / בוטלו', '≥ 30 % of ≥ 5 current tenders decided without a winner / cancelled') },
    'renewal-pipeline': { term: 'renewal_proposed_units', kind: 'watch', rule: bi('≥ 2,000 יח״ד מוצעות במתחמי התחדשות (כפי שפורסם)', '≥ 2,000 proposed units in renewal complexes (as published)') },
    'rental-pipeline': { term: 'rental_tender_units_vs_stated', kind: 'watch', rule: bi('≥ 3 מכרזי דיור להשכרה נוכחיים', '≥ 3 current rental-track tenders') },
    'stale-rental-status': { term: 'rental_tender_units_vs_stated', kind: 'risk', rule: bi('≥ 3 מכרזי השכרה שסטטוס הרשות שלהם לא התקדם מעל 36 חודשים', '≥ 3 rental tenders whose Authority status has not advanced for over 36 months') },
    'developer-entries': { term: 'market_entry', kind: 'watch', rule: bi('≥ 2 כניסות יזמים ליישוב ב-24 חודשים', '≥ 2 developer entries into the locality in 24 months') },
