    small_sample: { label: bi('מדגם קטן', 'Small sample'), why: bi('פחות מהסף שנקבע (למשל < 10 עסקאות, < 3 רשומות בחלון) — ללא חציון, מגמה או אחוז.', 'Below the stated threshold (e.g. < 10 transactions, < 3 records in a window) — no median, trend or percentage.'), unlock: bi('יותר תצפיות באותו היקף.', 'More observations in the same scope.'), ids: [] },
    source_unavailable: { label: bi('המקור אינו זמין', 'The source is unavailable'), why: bi('המקור דחה את הבדיקה (401/403/429) או נכשל; הנתון התקין האחרון נשמר ומתוארך — לעולם לא 0.', 'The source refused the check (401/403/429) or failed; the last valid data is kept and dated — never 0.'), unlock: bi('המקור עונה שוב (מצוין RECOVERED במרכז הנתונים).', 'The source answers again (RECOVERED in the Trust Center).'), ids: [] },
